use crate::aap::caps::state_read;

struct Node;

/// Keys the subscription list may be stored under. The store cannot be
/// enumerated, so the node asks for the names it knows, in order.
const KEYS: [&str; 6] = ["urls", "subscriptions", "feeds", "list", "all", "index"];

/// Extract every JSON string literal from `s`, unescaped.
fn quoted_strings(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('b') => cur.push('\u{8}'),
                    Some('f') => cur.push('\u{c}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        let mut ok = true;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if ok {
                            if let Some(ch) = char::from_u32(code) {
                                cur.push(ch);
                            }
                        }
                    }
                    Some(other) => cur.push(other),
                    None => break,
                },
                other => cur.push(other),
            }
        }
        if closed {
            out.push(cur);
        }
    }
    out
}

fn push_unique(urls: &mut Vec<String>, candidate: &str) {
    let t = candidate.trim();
    if t.is_empty() {
        return;
    }
    if !urls.iter().any(|u| u == t) {
        urls.push(t.to_string());
    }
}

/// Parse a stored value into URLs. Accepts JSON (an array of strings, or an
/// object containing one) or plain text separated by newlines, commas,
/// semicolons or whitespace, with `#` comment lines.
fn parse_urls(value: &str) -> Vec<String> {
    let mut urls = Vec::new();
    if value.contains('"') {
        let strings = quoted_strings(value);
        let any_url = strings.iter().any(|s| s.contains("://"));
        let in_array = value.trim_start().starts_with('[');
        for s in &strings {
            if s.contains("://") || (!any_url && in_array) {
                push_unique(&mut urls, s);
            }
        }
    } else {
        for line in value.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for tok in line.split(|c: char| c.is_whitespace() || c == ',' || c == ';') {
                let tok = tok.trim_matches(|c: char| c == '[' || c == ']');
                push_unique(&mut urls, tok);
            }
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS.iter() {
            if let Some(value) = state_read::get(key) {
                let urls = parse_urls(&value);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // No subscriptions are stored: the contract `present(urls)` cannot be
        // met honestly, so fail the node rather than fabricate a list.
        panic!("no subscriptions found in state store");
    }
}

export!(Node);
